// Invoke the self-check; no inputs and no persistent outputs are required.
int status = jess_self_check();
// Record the status in global attributes for potential cross-stub assertions.
FUZZ_SET_ATTR_INT_GLOBAL("jess_self_check_status", status);
// No outputs: status is ephemeral and there is no owned object to return.
// Validation: The stub exercises the API, captures the status for diagnostics, and avoids exporting transient stack data as a pooled object.

// Query the library version string. Per requirements, do not modify or free it.
const char *version = jess_version();
// Ensure we do not export a null pointer into the object pool.
if (!version) { FUZZ_BAIL(); }
// Light-touch validation: read the first byte to ensure the pointer is valid and readable.
volatile char _touch = version[0]; (void)_touch;
